import numpy as np
lines = open("opt1.xyz").read().splitlines()
els, xyz = [], []
for ln in lines[2:]:
    p = ln.split(); els.append(p[0]); xyz.append([float(p[1]),float(p[2]),float(p[3])])
xyz = np.array(xyz)
cov = {'H':0.31,'C':0.76,'N':0.71,'O':0.66,'F':0.57,'Rh':1.42}
n=len(els)
bonds=[]
for i in range(n):
    for j in range(i+1,n):
        dij=np.linalg.norm(xyz[i]-xyz[j])
        if dij < cov[els[i]]+cov[els[j]]+0.35:
            bonds.append((i,els[i],j,els[j],round(dij,3)))
# heavy-atom bonds only
print("=== Heavy atom bonds (dist) ===")
for i,ei,j,ej,dij in bonds:
    if ei!='H' and ej!='H':
        print(f"{ei}{i}-{ej}{j}: {dij}")
print("\n=== X-H counts ===")
from collections import defaultdict
hc=defaultdict(int)
for i,ei,j,ej,dij in bonds:
    if ej=='H': hc[i]+=1
    if ei=='H': hc[j]+=1
for i in sorted(hc):
    if els[i]!='H': print(f"{els[i]}{i}: {hc[i]} H")
